fn checked_array_access(ptr: *Int, len: Int, index: Int) -> Int {
  if ptr == null {
    io.eprintln("Error: null pointer");
    @llvm.trap();
  }
  if index < 0 || index >= len {
    io.eprintln("Error: index out of bounds");
    @llvm.trap();
  }
  return ptr[index];
}

fn main() -> Int {
  let arr = [10, 20, 30, 40];
  return checked_array_access(&arr[0], 4, 2);
}
